<?php
require_once __DIR__.'/../includes/admin_ui.php';
$edit=null;if(isset($_GET['edit'])){$q=$pdo->prepare("SELECT * FROM events WHERE id=?");$q->execute([(int)$_GET['edit']]);$edit=$q->fetch();}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf($_POST['csrf']??'');$id=(int)($_POST['id']??0);$d=[trim($_POST['title']),$_POST['event_type'],$_POST['event_date'],$_POST['start_time']?:null,$_POST['end_time']?:null,trim($_POST['description'])];if($id){$pdo->prepare("UPDATE events SET title=?,event_type=?,event_date=?,start_time=?,end_time=?,description=? WHERE id=?")->execute([...$d,$id]);audit($pdo,'update','Updated event #'.$id);go('events.php','Event updated successfully');}$pdo->prepare("INSERT INTO events(title,event_type,event_date,start_time,end_time,description) VALUES(?,?,?,?,?,?)")->execute($d);audit($pdo,'create','Created event');go('events.php','Event added successfully');}
if(isset($_GET['delete'])){$id=(int)$_GET['delete'];$pdo->prepare("DELETE FROM events WHERE id=?")->execute([$id]);audit($pdo,'delete','Deleted event #'.$id);go('events.php','Event deleted');}
$rows=$pdo->query("SELECT * FROM events ORDER BY event_date DESC,id DESC")->fetchAll();
admin_layout('Events','Plan and manage school events, exams, meetings and activities.');echo '<div class="actions"><button class="btn" data-modal="eventModal">＋ Add Event</button></div></div>';flash();
echo '<div class="card"><div class="toolbar"><input class="search" data-search="#eventTable" placeholder="Search event or type"><span class="muted">'.count($rows).' events</span></div><div class="table-wrap"><table class="table" id="eventTable"><thead><tr><th>Event</th><th>Type</th><th>Date</th><th>Time</th><th>Actions</th></tr></thead><tbody>';
foreach($rows as $r){echo '<tr><td><b>'.e($r['title']).'</b><br><span class="muted">'.e($r['description']??'').'</span></td><td><span class="badge">'.e($r['event_type']).'</span></td><td>'.e($r['event_date']).'</td><td>'.e(($r['start_time']??'').' - '.($r['end_time']??'' )).'</td><td class="actions-cell"><a class="btn light small" href="?edit='.$r['id'].'">Edit</a><a class="btn danger small" data-confirm="Delete this event?" href="?delete='.$r['id'].'">Delete</a></td></tr>';}
echo '</tbody></table></div></div><div class="modal" id="eventModal"><div class="modal-box"><div class="modal-head"><h2>'.($edit?'Edit Event':'Add Event').'</h2><button class="close">×</button></div><form class="form" method="post"><input type="hidden" name="csrf" value="'.e(csrf_token()).'"><input type="hidden" name="id" value="'.e((string)($edit['id']??0)).'"><div class="form-grid"><label>Event Title<input name="title" required value="'.e($edit['title']??'').'"></label><label>Event Type<select name="event_type">'.implode('',array_map(fn($x)=>'<option'.(($edit['event_type']??'')===$x?' selected':'').'>'.e($x).'</option>',['School Event','Exam','Parent Meeting','Holiday','Activity'])).'</select></label><label>Date<input type="date" name="event_date" required value="'.e($edit['event_date']??'').'"></label><label>Start Time<input type="time" name="start_time" value="'.e($edit['start_time']??'').'"></label><label>End Time<input type="time" name="end_time" value="'.e($edit['end_time']??'').'"></label><label class="form-full">Description<textarea name="description" rows="4">'.e($edit['description']??'').'</textarea></label></div><div class="form-actions"><button type="button" class="btn light close">Cancel</button><button class="btn">'.($edit?'Update Event':'Save Event').'</button></div></form></div></div>';if($edit)echo '<script>document.getElementById("eventModal").classList.add("show")</script>';admin_end();